<?php require_once __DIR__."/../config/auth.php";require_login();$rows=db()->query("SELECT i.*,u.name user_name FROM invoices i JOIN users u ON u.id=i.user_id ORDER BY i.id DESC LIMIT 300")->fetchAll();include __DIR__."/partials/header.php";?><header><h1><?=t("الفواتير","Invoices")?></h1></header><div class="card"><table><tr><th>Invoice</th><th>User</th><th>Total</th><th>Paid</th><th>Payment</th><th>Date</th></tr><?php foreach($rows as $r):?><tr><td><a href="receipt.php?id=<?=$r["id"]?>" target="_blank"><?=e($r["invoice_no"])?></a></td><td><?=e($r["user_name"])?></td><td><?=number_format($r["total"],2)?></td><td><?=number_format($r["paid"],2)?></td><td><?=e($r["payment_method"])?></td><td><?=e($r["created_at"])?></td></tr><?php endforeach;?></table></div><?php include __DIR__."/partials/footer.php";?>